/** Room codes are six upper-case hex characters, generated by the server. */
const ROOM_CODE = /^[0-9A-F]{6}$/;
export const normalizeRoomCode = (text: string) => text.replace(/[\s-]/g, '').toUpperCase().slice(0, 12);
export const roomCodeProblem = (code: string) => !code ? 'Enter the six-character room code.' : ROOM_CODE.test(code) ? '' : `"${code}" is not a room code. Codes have six letters A to F and numbers, like 5CDD4F.`;
export const inviteCode = (url: URL) => normalizeRoomCode(url.searchParams.get('room') || '');
export function inviteUrl(url: URL, code: string) { const invite = new URL(url.href); invite.search = ''; invite.hash = ''; invite.searchParams.set('room', code); return invite; }
